files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --border: #0f3460;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 16px 16px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  border: none;
}

label, legend {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0;
}

input {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.15s;
}

input:hover {
  border-color: var(--muted);
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.tip-buttons {
  display: flex;
  gap: 8px;
}

.tip-btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 4px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: transform 0.1s, background 0.15s, color 0.15s;
}

.tip-btn:hover {
  background: var(--border);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translateY(2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.results {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-top: 3px dashed var(--border);
  padding-top: 16px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  font-size: 0.9rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.result-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .result-value {
    font-size: 1.1rem;
  }
}

const billInput = document.getElementById('bill');
const peopleInput = document.getElementById('people');
const tipButtons = document.querySelectorAll('.tip-btn');
const tipPerPersonEl = document.getElementById('tipPerPerson');
const totalPerPersonEl = document.getElementById('totalPerPerson');

let selectedTip = 0;

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function update() {
  const bill = parseFloat(billInput.value);
  const people = parseInt(peopleInput.value, 10);

  if (!isFinite(bill) || bill < 0 || !isFinite(people) || people < 1) {
    tipPerPersonEl.textContent = '$0.00';
    totalPerPersonEl.textContent = '$0.00';
    return;
  }

  const tipTotal = bill * (selectedTip / 100);
  const tipPerPerson = tipTotal / people;
  const totalPerPerson = (bill + tipTotal) / people;

  tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
  totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
}

function selectTip(percent) {
  selectedTip = percent;
  tipButtons.forEach(btn => {
    btn.setAttribute('aria-pressed', String(Number(btn.dataset.tip) === percent));
  });
  update();
}

tipButtons.forEach(btn => {
  btn.addEventListener('click', () => selectTip(Number(btn.dataset.tip)));
});

billInput.addEventListener('input', update);
peopleInput.addEventListener('input', update);

selectTip(15);
